'use client'

import * as React from 'react'

// The component brings its own styles. Without this a `gamestage-ui add` installs a
// working but completely unstyled Segments, and `tsc --noEmit` passes on it, so
// the gate cannot catch it.
import './segments.css'

/**
 * Segments: a bounded run drawn as a row of cells rather than one continuous
 * fill.
 *
 * GSUI-115. The design draws this object three separate times with three
 * treatments, and it is the same object each time: the round indicator on
 * specimen 3c ("5 rounds, current lit"), the segmented progress under a quest
 * ("2/3"), and the story pager on specimen 3g. Building three of them is how a
 * library ends up with three names for a track, so there is one component and a
 * `presentation` that says which treatment is rendering. `choice` and
 * `selector` already work that way.
 *
 * There is no `data-gs-progress` and no `data-gs-fill`. How far through
 * something is, is `data-gs-value` over `data-gs-max`, the same as every other
 * bounded value in the library, and here the value is the number of segments
 * behind the player.
 *
 * Every state is readable without colour, which is the rule this component is
 * most at risk of breaking because a segment is small. A complete segment is
 * filled and carries a tick. A wrong one is striped and carries a cross, which
 * is the design's own instruction on specimen 3c: "wrong segments are striped,
 * not just red". An active one is wider and ringed. An empty one is hollow.
 * Four shapes, four glyphs or their absence, before any hue is applied.
 *
 * It performs nothing. It does not count, advance, or decide that a segment is
 * won. The host passes the states in.
 */

/**
 * What is true of one segment.
 *
 * `empty` is not the absence of a state. A run of five segments with three
 * behind the player still renders five, because "two to go" is the thing the
 * player reads.
 */
export type SegmentState = 'empty' | 'complete' | 'wrong' | 'active'

export interface Segment {
  /** The host's own id for this segment, if it has one. */
  id?: string
  /** What is true of it. Defaults to `empty`. */
  state?: SegmentState
  /** What a screen reader hears for this segment, after its position. */
  label?: string
  /** What rides inside the segment: a multiplier, a round number, a mark. */
  children?: React.ReactNode
}

export interface SegmentsProps
  extends Omit<React.HTMLAttributes<HTMLDivElement>, 'children'> {
  /** The run, in order. One element per segment, always rendered. */
  segments: Segment[]
  /**
   * Which treatment is rendering.
   *
   * `bar` is the segmented progress bar: equal rounded cells side by side.
   * `dots` is the round indicator: equal circles, which is what a marker on a
   * milestone track is. `pager` is the story pager: small cells where the one
   * the sequence is on widens into a pill, so position is readable from shape
   * at a glance and from a distance.
   */
  presentation?: 'bar' | 'dots' | 'pager'
  /** The word a player reads as this run's name. */
  label?: string
  /** Render the count beside the run, as the design's quest card does. */
  showSummary?: boolean
}

/** From the contract's table of state words, so no component invents its own. */
const STATE_WORD = {
  complete: 'complete',
  wrong: 'wrong',
  active: 'current',
  empty: 'to go',
} as const

/**
 * Inline SVG taking `currentColor`, never an emoji: an emoji carries its own
 * palette, ignores the theme and renders differently on every platform, which
 * is three ways of failing the rule that a state is never a colour alone.
 */
function Tick() {
  return (
    <svg viewBox="0 0 12 12" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <path d="M2.5 6.5 5 9l4.5-6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" />
    </svg>
  )
}

function Cross() {
  return (
    <svg viewBox="0 0 12 12" width="1em" height="1em" fill="none" aria-hidden="true" focusable="false">
      <path d="M3 3l6 6M9 3l-6 6" stroke="currentColor" strokeWidth="2" strokeLinecap="round" />
    </svg>
  )
}

/** A segment that is behind the player or lost to them says so with a mark. */
const GLYPH: Partial<Record<SegmentState, () => React.ReactElement>> = {
  complete: Tick,
  wrong: Cross,
}

/**
 * How many segments are behind the player.
 *
 * A wrong segment counts as behind: the round was played and it is over. That
 * is what makes `data-gs-value` over `data-gs-max` mean "3 of 5 played" rather
 * than "3 of 5 won", and the per-segment `data-gs-state` is what tells the two
 * apart. Exported so `quest` and `milestones` count the same way rather than
 * each deciding.
 */
export function segmentsBehind(segments: Segment[]): number {
  return segments.filter((s) => s.state === 'complete' || s.state === 'wrong').length
}

export function Segments({
  segments,
  presentation = 'bar',
  label = 'progress',
  showSummary = false,
  className,
  ...rest
}: SegmentsProps) {
  const max = segments.length
  const value = segmentsBehind(segments)

  // The name carries the run, because a screen reader user gets no fill, no
  // stripe and no shape. Order: what it is, then where it is.
  const words = [label, `${value} of ${max}`]

  return (
    <div
      {...rest}
      className={['gs-segments', className].filter(Boolean).join(' ')}
      data-gs-component="segments"
      data-gs-presentation={presentation}
      data-gs-value={value}
      data-gs-max={max}
      data-gs-complete={max > 0 && value === max ? 'true' : undefined}
      role="group"
      aria-label={words.join(', ')}
    >
      {/* A list, so a screen reader can walk the segments one at a time and
          hear which two of the five were lost. The group above carries the
          summary; this carries the detail. */}
      <div className="gs-segments__track" data-gs-scope="segments" data-gs-part="track" role="list">
        {segments.map((segment, index) => {
          const state = segment.state ?? 'empty'
          const Glyph = GLYPH[state]
          // Each segment is announced on its own, because "3 of 5" does not say
          // which two were lost. The position comes first so the list reads in
          // order however the states fall.
          const segmentWords = [`${index + 1}`, segment.label, STATE_WORD[state]].filter(Boolean)
          return (
            <span
              key={segment.id ?? index}
              className="gs-segments__segment"
              data-gs-scope="segments" data-gs-part="segment"
              // The same attribute a tutorial step and a story segment use. A
              // segment's position in its run is the same idea as a step's.
              data-gs-step={index + 1}
              data-gs-complete={state === 'complete' ? 'true' : undefined}
              data-gs-state={state === 'wrong' ? 'wrong' : undefined}
              data-gs-active={state === 'active' ? 'true' : undefined}
              // The fill and the width move, so they are motion and stop dead
              // under reduced motion. The stripe, the glyph and the border are
              // emphasis and survive, which is how a player who sees no
              // movement still reads the run.
              data-gs-animates="motion"
              role="listitem"
              aria-label={segmentWords.join(', ')}
            >
              {Glyph ? (
                <span
                  className="gs-segments__glyph"
                  data-gs-scope="segments" data-gs-part="glyph"
                  data-gs-animates="emphasis"
                  aria-hidden="true"
                >
                  <Glyph />
                </span>
              ) : null}
              {segment.children ? (
                <span className="gs-segments__content" data-gs-scope="segments" data-gs-part="label" aria-hidden="true">
                  {segment.children}
                </span>
              ) : null}
            </span>
          )
        })}
      </div>

      {showSummary ? (
        // aria-hidden: the group's label above already carries "2 of 3", and
        // announcing it again reads the count twice.
        <span className="gs-segments__summary" data-gs-scope="segments" data-gs-part="summary" aria-hidden="true">
          {value}/{max}
        </span>
      ) : null}
    </div>
  )
}

/* Segments. Every value comes from a token; nothing here is a literal colour,
   size, duration or typeface.

   One stylesheet, three treatments, because they are one object. The shared
   rules come first and each `[data-gs-presentation]` block below changes only
   the geometry. A fourth treatment adds a block; it does not add a component. */

.gs-segments {
  display: flex;
  align-items: center;
  gap: var(--gs-space-2);
  width: 100%;
}

.gs-segments__track {
  display: flex;
  align-items: center;
  gap: var(--gs-space-1);
  flex: 1;
  min-width: 0;
}

/* The cell. Hollow by default, because "three to go" is a state a player
   reads and not an absence. */
.gs-segments__segment {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;

  box-sizing: border-box;
  background: var(--gs-color-surface);
  border: var(--gs-stroke-hairline) solid var(--gs-color-edge);
  box-shadow: var(--gs-depth-flat);
  color: var(--gs-color-ink-secondary);

  /* Width and colour both move as a run advances. Only these are timed, so
     reduced motion zeroes the travel and leaves the stripe, the glyph and the
     border, which is what carries the state without it. */
  transition:
    width var(--gs-motion-fill) ease-out,
    flex-grow var(--gs-motion-fill) ease-out,
    background var(--gs-motion-fill) ease-out;
}

/* -- complete ------------------------------------------------------------- */
/* Three channels at once, per the contract: a solid fill, a tick, and an edge
   that is no longer a hairline. */
.gs-segments__segment[data-gs-complete='true'] {
  background: var(--gs-color-positive);
  border-color: var(--gs-color-positive-base);
  color: var(--gs-color-on-bright);
}

/* -- wrong ---------------------------------------------------------------- */
/* "wrong segments are striped, not just red", from specimen 3c, and the same
   three-channel rule as every other result state: the ground, the texture and
   the cross. A player who cannot tell this ground from the positive one still
   reads the stripe, and the cross is there either way.

   The ground is set with the `background` shorthand and the stripe lives on a
   pseudo-element, which looks like one declaration too many and is not.
   `--gs-color-negative` is a plain colour in three themes and a
   `linear-gradient` in arcade, so `background-color: var(--gs-color-negative)`
   is an invalid declaration there and the browser drops it silently: the ground
   would simply vanish in one theme and nothing would fail. The shorthand takes
   either, and a shorthand cannot also carry the stripe, so the stripe moves off
   the element. */
.gs-segments__segment[data-gs-state='wrong'] {
  border-color: var(--gs-color-negative-base);
  color: var(--gs-color-on-bright);
  background: var(--gs-color-negative);
}

.gs-segments__segment[data-gs-state='wrong']::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: inherit;
  background-image: repeating-linear-gradient(
    -45deg,
    var(--gs-color-negative-base) 0,
    var(--gs-color-negative-base) 2px,
    transparent 2px,
    transparent 6px
  );
}

/* -- active --------------------------------------------------------------- */
/* Lit, ringed and taller than its neighbours. Shape rather than glow alone,
   because a glow is the channel a low-contrast screen loses first. */
.gs-segments__segment[data-gs-active='true'] {
  background: var(--gs-color-reward);
  border-color: var(--gs-color-reward-base);
  border-width: var(--gs-stroke-selected);
  color: var(--gs-color-on-bright);
  box-shadow: var(--gs-depth-reward);
}

/* Above the stripe, which is an absolutely positioned pseudo-element and would
   otherwise paint over the mark that carries the state. */
.gs-segments__glyph,
.gs-segments__content {
  position: relative;
}

.gs-segments__glyph {
  display: flex;
  line-height: 1;
  /* Emphasis, not motion: this duration survives reduced motion on purpose. */
  transition: opacity var(--gs-motion-emphasis) ease-out;
}

.gs-segments__content {
  font-family: var(--gs-type-stat-font-family);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  line-height: 1;
}

.gs-segments__summary {
  font-family: var(--gs-type-stat-font-family);
  font-size: var(--gs-type-label-font-size);
  font-weight: var(--gs-type-stat-font-weight);
  font-variant-numeric: var(--gs-type-score-font-variant-numeric);
  color: var(--gs-color-ink);
  flex: none;
}

/* -- bar: the segmented progress bar -------------------------------------- */
/* Equal cells sharing the run. This is the quest card's "2/3" row and the
   round indicator's five rounds. */
.gs-segments[data-gs-presentation='bar'] .gs-segments__segment {
  flex: 1 1 0;
  min-width: 0;
  height: var(--gs-size-icon-utility);
  border-radius: var(--gs-radius-sm);
  font-size: var(--gs-type-label-font-size);
}

/* -- dots: the round indicator -------------------------------------------- */
/* Equal circles. A milestone marker is one of these with something inside it,
   which is why a milestone is not a second component. */
.gs-segments[data-gs-presentation='dots'] .gs-segments__track {
  gap: var(--gs-space-2);
}

.gs-segments[data-gs-presentation='dots'] .gs-segments__segment {
  flex: none;
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
  font-size: var(--gs-type-label-font-size);
}

/* -- pager: the story pager ----------------------------------------------- */
/* Cells where the one the sequence is on widens into a pill. Position is then
   readable from shape alone, which is the point: a pager sits under a title at
   the size where hue is the first thing to go.

   The design draws these smaller than this. They are sized to the control icon
   so a completed step's tick fits inside one: a mark that overflows its cell is
   not a mark, and a pager that dropped the mark would be saying "behind you"
   in fill alone. Shape is still doing the work; the glyph is the second
   channel rather than the only one. */
.gs-segments[data-gs-presentation='pager'] .gs-segments__track {
  flex: none;
}

.gs-segments[data-gs-presentation='pager'] .gs-segments__segment {
  flex: none;
  width: var(--gs-size-icon-control);
  height: var(--gs-size-icon-control);
  border-radius: var(--gs-radius-full);
  font-size: var(--gs-type-label-font-size);
}

.gs-segments[data-gs-presentation='pager'] .gs-segments__segment[data-gs-active='true'] {
  width: var(--gs-size-icon-hero);
}
